export const renderNormDetailed: RichRenderFn = createRenderer(normConfig);
export const renderEmbeddingDetailed: RichRenderFn = createRenderer(embeddingConfig);
export const renderMoeDetailed: RichRenderFn = createRenderer(moeConfig);
export const renderResidualDetailed: RichRenderFn = createRenderer(residualConfig);
export const renderLmHeadDetailed: RichRenderFn = createRenderer(lmHeadConfig);
export const renderPositionalEncodingDetailed: RichRenderFn = createRenderer(positionalEncodingConfig);
export const renderArchitectureComparisonDetailed: RichRenderFn = (g, _params, _meta, _graph) => {
  const totalW = 800;
  const cx = totalW / 2;
  let y = 30;

  drawLabel(g, cx, y, 'Transformer Architecture Comparison', { size: 16, weight: '700' });
  y += 22;
  drawLabel(g, cx, y, 'Encoder-only vs Decoder-only vs Encoder-Decoder', { size: 10, color: '#888' });
  y += 28;

  drawTensor(g, cx - 130, y, 260, 30, 'tokens: [b, seq]  (task-dependent)', '#e8f5e9', '#4caf50');
  y += 45;

  drawArrow(g, cx, y - 10, cx, y);
  y += 8;

  const colW = 230;
  const gap = 20;
  const totalCols = 3 * colW + 2 * gap;
  const startX = cx - totalCols / 2;
  const cols = [
    { x: startX, color: '#4caf50', fill: '#e8f5e9' },
    { x: startX + colW + gap, color: '#1976d2', fill: '#e3f2fd' },
    { x: startX + 2 * (colW + gap), color: '#7b1fa2', fill: '#f3e5f5' },
  ];

  const forkY = y;
  cols.forEach((c) => {
    const midX = c.x + colW / 2;
    drawArrow(g, cx, forkY, midX, forkY + 18, { color: '#78909c' });
  });
  y = forkY + 24;

  const archs = [
    {
      name: 'Encoder-only',
      model: 'BERT / RoBERTa',
      task: 'Classification / NER',
      steps: ['Embed + Pos Encoding', 'Bidirectional Self-Attn', 'Layer Norm + FFN', 'x N layers'],
      mask: 'full' as const,
      maskLabel: 'Full attention (bidirectional)',
    },
    {
      name: 'Decoder-only',
      model: 'GPT / Llama',
      task: 'Generation / Chat',
      steps: ['Embed + Pos Encoding', 'Causal Masked Self-Attn', 'Layer Norm + FFN', 'x N layers'],
      mask: 'causal' as const,
      maskLabel: 'Causal mask (autoregressive)',
    },
    {
      name: 'Encoder-Decoder',
      model: 'T5 / BART',
      task: 'Translation / Summarization',
      steps: ['Enc: Bidirectional Attn', 'Dec: Causal + Cross-Attn', 'Layer Norm + FFN', 'x N layers'],
      mask: 'cross' as const,
      maskLabel: 'Cross-attention (enc -> dec)',
    },
  ];

  const headerH = 46;
  const maskH = 55;
  const stepBoxH = 26;
  const stepGap = 4;

  archs.forEach((arch, ci) => {
    const c = cols[ci];
    const cg = g.append('g').attr('transform', `translate(${c.x}, ${y})`);

    cg.append('rect')
      .attr('width', colW).attr('height', headerH).attr('rx', 6)
      .attr('fill', c.fill).attr('stroke', c.color).attr('stroke-width', 1.5);
    drawLabel(cg as unknown as Sel, colW / 2, 14, arch.name, { size: 13, weight: '700', color: c.color });
    drawLabel(cg as unknown as Sel, colW / 2, 30, arch.model, { size: 9, font: 'monospace', color: '#666' });
    drawLabel(cg as unknown as Sel, colW / 2, 42, arch.task, { size: 8, color: '#999' });

    let iy = headerH + 12;
    drawArrow(cg as unknown as Sel, colW / 2, iy - 8, colW / 2, iy, { color: c.color });
    iy += 4;

    const maskG = cg.append('g').attr('transform', `translate(${colW / 2 - maskH / 2}, ${iy})`);
    const n = 6;
    const cellSz = maskH / n;
    for (let r = 0; r < n; r++) {
      for (let cc2 = 0; cc2 < n; cc2++) {
        let vis: boolean;
        if (arch.mask === 'full') vis = true;
        else if (arch.mask === 'causal') vis = cc2 <= r;
        else vis = true;
        maskG.append('rect')
          .attr('x', cc2 * cellSz).attr('y', r * cellSz)
          .attr('width', cellSz - 1).attr('height', cellSz - 1)
          .attr('rx', 1).attr('fill', vis ? c.color : '#f5f5f5')
          .attr('opacity', vis ? 0.55 : 0.15)
          .attr('stroke', c.color).attr('stroke-width', 0.3);
      }
    }
    if (arch.mask === 'cross') {
      for (let r = 0; r < n; r++) {
        for (let cc2 = 0; cc2 < n; cc2++) {
          maskG.append('circle')
            .attr('cx', cc2 * cellSz + cellSz / 2)
            .attr('cy', r * cellSz + cellSz / 2)
            .attr('r', 1.5).attr('fill', c.color).attr('opacity', 0.6);
        }
      }
    }
    drawLabel(cg as unknown as Sel, colW / 2, iy + maskH + 10, arch.maskLabel, { size: 8, color: '#666' });
    iy += maskH + 20;

    arch.steps.forEach((step, si) => {
      drawArrow(cg as unknown as Sel, colW / 2, iy - 4, colW / 2, iy, { color: '#ccc' });
      iy += 4;
      const isSpecial = si === 1;
      cg.append('rect')
        .attr('x', 10).attr('y', iy).attr('width', colW - 20).attr('height', stepBoxH).attr('rx', 4)
        .attr('fill', isSpecial ? c.fill : '#fafafa')
        .attr('stroke', isSpecial ? c.color : '#ddd').attr('stroke-width', isSpecial ? 1.5 : 0.5);
      drawLabel(cg as unknown as Sel, colW / 2, iy + stepBoxH / 2, step, {
        size: 9, weight: isSpecial ? '600' : '400', color: isSpecial ? c.color : '#555',
      });
      iy += stepBoxH + stepGap;
    });
  });

  y += headerH + 12 + 4 + maskH + 20 + (4 * (stepBoxH + stepGap)) + 20;

  drawArrow(g, cx, y - 10, cx, y);
  y += 8;
  drawTensor(g, cx - 130, y, 260, 30, 'logits / representations  (task-dependent)', '#e8f5e9', '#4caf50');
  y += 48;

  const tblX = cx - 330;
  const rows = [
    ['Property', 'Encoder-only', 'Decoder-only', 'Encoder-Decoder'],
    ['Attention', 'Bidirectional', 'Causal (masked)', 'Cross + Causal'],
    ['Pre-training', 'MLM (masked LM)', 'Next-token predict', 'Span corruption'],
    ['Fine-tuning', 'Classification head', 'In-context / instruct', 'Seq2seq task'],
    ['Scaling winner', 'Understanding tasks', 'Unified + generative', 'Translation / summar.'],
    ['Examples', 'BERT, RoBERTa', 'GPT, Llama, Claude', 'T5, BART, mBART'],
  ];
  const rowH = 22;
  const colWidths = [120, 160, 180, 200];
  const headerColors = ['#666', '#4caf50', '#1976d2', '#7b1fa2'];

  rows.forEach((row, ri) => {
    let rx = tblX;
    row.forEach((cell, ci) => {
      const cw = colWidths[ci];
      g.append('rect')
        .attr('x', rx).attr('y', y).attr('width', cw).attr('height', rowH).attr('rx', ri === 0 ? 4 : 0)
        .attr('fill', ri === 0 ? '#f5f5f5' : (ri % 2 === 0 ? '#fafafa' : '#fff'))
        .attr('stroke', '#e0e0e0').attr('stroke-width', 0.5);
      drawLabel(g, rx + 8, y + rowH / 2, cell, {
        size: ri === 0 ? 9 : 9, weight: ri === 0 || ci === 0 ? '700' : '400',
        color: ri === 0 ? headerColors[ci] : (ci === 0 ? '#555' : '#333'), anchor: 'start',
      });
      rx += cw;
    });
    y += rowH;
  });
  y += 20;

  y = drawExplanation(g, cx - 330, y, 660,
    'Encoder-only models (BERT, RoBERTa) see all positions bidirectionally, excelling at understanding tasks. '
    + 'Decoder-only models (GPT, Llama) use causal masking for autoregressive generation and now dominate LLM research. '
    + 'Encoder-Decoder models (T5, BART) handle sequence-to-sequence tasks like translation and summarization naturally.',
    'insight',
  );
  y = drawExplanation(g, cx - 330, y, 660,
    'Decoder-only architectures have won the scaling race: they unify understanding and generation in a single framework, '
    + 'simplify training (one loss function), and scale predictably. Encoder-Decoder can be more parameter-efficient for '
    + 'translation but requires two forward passes.',
    'perf',
  );

  y = drawCodeAnnotation(g, cx - 330, y, 660,
    'Architecture Paradigms — BERT, GPT, T5',
    [
      'The key difference is the attention mask: bidirectional, causal, or both.',
      'Modern LLMs are overwhelmingly decoder-only for unified pre-training and generation.',
    ],
    [
      '# Encoder-only (BERT): full bidirectional attention',
      'attn_mask = None                         # attend to all positions',
      '',
      '# Decoder-only (GPT): causal mask',
      'attn_mask = torch.tril(ones(seq, seq))   # attend to past only',
      '',
      '# Encoder-Decoder (T5): cross-attention',
      'h_dec = decoder_cross_attn(q=h_dec, k=h_enc, v=h_enc)',
    ],
  );

  return { width: totalW, height: y + 20, steps: [] };
};
export const renderRagDetailed: RichRenderFn = createRenderer(ragConfig);
